@module groupManager  src=groupManager.lua  loc=864  mode=chunk  self=gm
@deps tm, ds

# Invariants & contracts
  @contract  rehydrate on a groups invalidate (undo rewind); own assign echoes lack it, ignored  @ 623

# Shapes
  @shape  group = { rect, events = { [vuid]=groupEvt }, nextVuid, instances = { [instId]=instance } }  @ 3
  @shape  instance = { anchor = { ppq, chan, [laneDelta] }, assigns, adds, deletes }  -- pure data, persisted verbatim  @ 4
  @shape  proj[groupId][instId][vuid] = { uuid, groupEvt=clone, evt=liveEvt }  -- module-level, runtime; only `uuid` serialised, persisted as `uuids[groupId][instId][vuid]`  @ 5
  @shape  persisted groups = { groups = groups, uuids = { [groupId]={ [instId]={ [vuid]=uuid } } } }  @ 6

# Imports
  @require util = 'util'  @ 10
      @invariant  localMode is a single global UI flag; off (default), edits propagate to every sibling  @ 7
      @invariant  a staged edit matches its vuid by evt-table identity, else falls to the rect predicate  @ 8
  @require groupsCore = 'groups'  @ 11
  @require perf = 'perf'  @ 12

