  @fn keyOf(evt)  @ 95-99
  @fn copyScalars(src, dst)  @ 104-107
      --           every src field except DERIVED is carried, so mm's
      --           arbitrary per-event metadata (rpb included) survives.
      @invariant  payload crossing the group<->instance frame is opt-OUT --  @ 101
  @fn toGroup(evt, anchor)  @ 112-125
      -- Group dur is the note's INTENT ceiling span (endppq - onset), never the realised end tm
      -- re-derives every rebuild -- see docs/groupManager.md § Intent in, realisation out.
      @invariant  pb group-frame val is INTENT; toGroup reads evt.cents, not realised val  @ 111
  @fn toInstance(g, anchor)  @ 129-144
      -- A nil group dur is an open note (author endppq = util.OPEN); a finite dur is the intent
      -- ceiling (author endppq = onset + dur); tm stamps endppqL and regrows the tail on a blocker delete, never merely clips.
  @fn onTake(e)  @ 148-150
      -- Off-take concretes withheld: writing one pushes REAPER's EOT and grows the take.
      -- Group retains the member; concrete revives once an instance brings it on-take.
  @fn updToGroup(update, anchor, groupEvt)  @ 154-169
      -- Instance-frame partial update -> group-frame partial update; groupEvt is the event's
      -- current group entry (ceiling<->dur reference) -- see docs/groupManager.md § Intent in, realisation out.
  @fn updToInstance(update, anchor, groupEvt)  @ 173-193
      -- Exact inverse of updToGroup: dur removed, or a move of an already-open note, authors
      -- endppq=util.OPEN; else authors the intent ceiling on endppq -- tm stamps endppqL and derives the raw tail.
  @fn diffGroup(oldG, newG)  @ 196-205
      -- Neutral field diff between two group events (feeds updToInstance).
  -- Persistence
  @fn persist()  @ 209-221
  @fn rehydrate()  @ 225-247
      -- Construction-time cm read runs before any take binds, so it is empty; live data arrives
      -- only on the take-changed rebuild -- without rehydrate, restored groups are inert and nextGroupId clobbers on the next markGroup.
  -- Helpers
  @fn freshInstance(anchor)  @ 251-253
  @fn nextKey(map)  @ 255-259
  @fn sameSlot(a, b)  @ 263-266
      -- Two group-frame events occupy the same region slot: same onset, same channel offset, same
      -- stream -- the identity the override-transition helpers (revive, sibling absorb) match on.
  @fn revivableVuid(group, instance, evt)  @ 270-276
      -- A global-mode create on a slot this instance locally deleted: revives the shadowed group
      -- event in place instead of allocating a coincident vuid -- see docs/groupManager.md § localMode.
  @fn absorbSiblingOverrides(group, vuid, actingInstId, created)  @ 280-306
      -- A global-mode create/delete flips whether a shared event exists at a slot; a sibling's
      -- own override there is re-expressed across the flip -- see docs/groupManager.md § Override transitions.
  @fn classifyCreate(evt)  @ 310-321
      -- Positional lookup: does evt fall inside some instance's region, on a
      -- stream the region already selects? inRect enforces the gate.
  @fn rectCells(rect, anchor)  @ 326-337
      -- Overlapping mirror groups have no defined semantics (classifyCreate takes pairs()'s first
      -- match); regions are kept disjoint instead -- see docs/groupManager.md § Regions are disjoint.
  @fn spansOverlap(aPpq, aDur, bPpq, bDur)  @ 339-341
  @fn regionConflict(rect, anchor, exclude)  @ 345-364
      -- groupId of an existing group an instance of `rect` at `anchor` would collide with --
      -- shared time span AND a shared (channel, streamId) cell -- or nil.
  @fn originAnchor(rect)  @ 367
      -- markGroup seats instance 1 at the rect's own origin; a caller gating before it asks about the same anchor.
  -- Active group (dupeClip-idiom selector; the command layer owns the
  -- clear-on-other-command lifetime, gm only the pointer)
  -- SEAM
  @fn reproject(groupId)  @ 535-562
