  @api gm:deletedCells(groupId, instId)  @ 503-513
      -- Tagged with vuid so revertDelete can lift each override. A dropped group event
      -- (group is authority) leaves a moot delete -- skipped.
      @contract  (groupId, instId) -> { { vuid, evt } }; evt = toInstance projection of an empty cell  @ 502
  @api gm:footprintAliases(cells)  @ 518-531
      -- Precise per-cell injectivity test for propagating block ops (decision 3): two cells
      -- on one group slot => non-injective; disjoint slots stay legal. see docs/groupManager.md § Block-shift injectivity.
      @contract  (cells) -> bool. cells carry { ppq, chan, evType, lane?/cc? }.  @ 517
  -- INSTANCE / GROUP LIFECYCLE
  @api gm:deleteInstance(groupId, instId)  @ 633-653
      -- Cascades: dropping the group's last instance also drops the group,
      -- clearing activeGroup if it pointed here (else it would dangle).
      @contract  (groupId, instId) -> true | nil,reason. Unknown id -> nil,reason.  @ 632
  @api gm:moveInstance(groupId, instId, anchor)  @ 658-697
      -- Re-anchor directly (reproject can't see anchor-invariant moves; see docs/groupManager.md
      -- § Instance lifecycle). onTake withholds off-take members and revives on return (bottom only).
      @contract  (groupId, instId, anchor) -> true | nil,reason. Caller cleared dest + clamped top.  @ 657
  @api gm:addEvent(evt)  @ 702-725
      -- Positional create (the add half of a facade move): classifyCreate finds the covering
      -- region; global adopts into the shared pattern (all instances gain it), localMode keeps a per-instance add.
      @contract  (evt) -> true | nil,'not in a region'. Defers to reproject; never links clone.  @ 701
  @api gm:deleteEvent(uuid)  @ 730-751
      -- Delete a member: drop the shared event (synced), peel an override back to
      -- synced, or hide locally. See docs/groupManager.md § Override transitions.
      @contract  (uuid) -> true | nil,reason  @ 729
  @api gm:revertDelete(groupId, instId, vuid)  @ 756-763
      -- The group event was never removed (only shadowed), so reproject revives the synced concrete.
      -- delete-ov + delete -> revert to synced; see docs/groupManager.md.
      @contract  (groupId, instId, vuid) -> true | nil,reason  @ 755
  @api gm:assignEvent(uuid, update)  @ 768-802
      -- Value edit of a member (assign half of the facade): localMode or an existing override
      -- => sticky localAmend, else edit the shared pattern. Consumes tv's AUTHORED update (updToGroup).
      @contract  (uuid, update) -> true | nil,'not a member'. Defers to reproject (pendingReproject).  @ 767
  @api gm:resizeGroup(groupId, instId, edits)  @ 807-862
      -- Resizes the SHARED rect from edge instance `instId`'s drag (Model A re-origin); a member
      -- the new rect drops leaves the group, `gained` folds in at instId's anchor -- see docs/groupManager.md § Instance lifecycle & region resize.
      @contract  (groupId, instId, {startDelta?,endDelta?,streams?,gained?}) -> true|nil,reason.  @ 806

